@pytest.mark.browser @pytest.mark.requirements('STV_SWR_050','STV_SWR_063','STV_SWR_064','STV_SWR_065') @pytest.mark.parametrize('protocol',['file','http']) @pytest.mark.parametrize('limit',[None,3]) def test_persistent_stack_fifo_scope_navigation_and_responsive_layout(browser,short_output,protocol,limit): source=short_output/'source';prepare_source(source,limit);result=build(source,short_output/'html');assert result.returncode==0,result.stdout+result.stderr with published_url(short_output/'html',protocol) as url: browser.set_window_size(1600,1200);browser.get(url);wait=WebDriverWait(browser,20) wait.until(lambda d:len(d.find_elements(By.CSS_SELECTOR,'.stv-view[data-stv-revision="0"]'))==2) root,other=browser.find_elements(By.CSS_SELECTOR,'.stv-view') world=browser.execute_script("return [...arguments[0].querySelectorAll('.stv-node')].map(n=>[n.dataset.key,n.style.left,n.style.top])",root) for id in IDS[:3]:open_box(browser,root,id) wait.until(lambda d:'Long rendered' in panel(browser,root,IDS[0]).text) first=panel(browser,root,IDS[0]);identity=first.get_attribute('id');open_box(browser,root,IDS[0]) assert panel(browser,root,IDS[0]).get_attribute('id')==identity assert panel_ids(browser,root)==IDS[:3] assert browser.execute_script("return document.activeElement.closest('.stv-persistent-detail').dataset.needId")==IDS[0] # Hover has its own timer/panel and consumes no persistent slot. node=browser.execute_script("return [...arguments[0].querySelectorAll('.stv-node')].find(n=>JSON.parse(n.dataset.key)[1]===arguments[1])",root,IDS[0]) toolbar(browser,root,'Reset viewport');browser.execute_script('arguments[0].scrollIntoView({block:"center"})',node);ActionChains(browser).move_to_element(node).perform();wait.until(lambda d:d.find_elements(By.CSS_SELECTOR,'.stv-hover-detail input')) assert panel_ids(browser,root)==IDS[:3] ids=browser.execute_script("return [...document.querySelectorAll('[id]')].map(n=>n.id)");assert len(ids)==len(set(ids)) browser.switch_to.active_element.send_keys(Keys.ESCAPE);assert not browser.find_elements(By.CSS_SELECTOR,'.stv-hover-detail') assert panel_ids(browser,root)==IDS[:3] panel(browser,root,IDS[1]).find_element(By.CSS_SELECTOR,'button').send_keys(Keys.ENTER) open_box(browser,root,IDS[3]);assert panel_ids(browser,root)==[IDS[0],IDS[2],IDS[3]] for id in IDS[4:]:open_box(browser,root,id) expected=IDS[2:] if limit is None else IDS[9:] assert panel_ids(browser,root)==expected panel(browser,root,expected[0]).find_element(By.CSS_SELECTOR,'button').click() # Manual close frees one slot; reopening appends without evicting. open_box(browser,root,expected[0]);expected=expected[1:]+expected[:1];assert panel_ids(browser,root)==expected browser.execute_script('arguments[0].focus()',panel(browser,root,expected[0]));open_box(browser,root,IDS[1]);expected=expected[1:]+[IDS[1]] assert panel_ids(browser,root)==expected assert browser.execute_script("return [...arguments[0].querySelectorAll('.stv-node')].map(n=>[n.dataset.key,n.style.left,n.style.top])",root)==world assert browser.execute_script("const r=arguments[0].getBoundingClientRect(),b=arguments[0].querySelector('.stv-close-all').getBoundingClientRect();return r.right-b.right<20&&b.right<=r.right",root) > assert browser.execute_script("const v=arguments[0].querySelector('.stv-viewport').getBoundingClientRect(),s=arguments[0].querySelector('.stv-details-stack').getBoundingClientRect();return s.left>=v.right-1",root) E assert False E + where False = execute_script("const v=arguments[0].querySelector('.stv-viewport').getBoundingClientRect(),s=arguments[0].querySelector('.stv-details-stack').getBoundingClientRect();return s.left>=v.right-1", <selenium.webdriver.remote.webelement.WebElement (session="acc78dd0-7a86-469f-9696-4f32ba68901d", element="b71f3837-5d7f-419f-91a8-aab2fa04b212")>) E + where execute_script = <selenium.webdriver.firefox.webdriver.WebDriver (session="acc78dd0-7a86-469f-9696-4f32ba68901d")>.execute_script
